import { getServerSession } from "next-auth";
import { redirect } from "next/navigation";
import { authOptions } from "@/lib/auth";
import { db } from "@/lib/db";
import Link from "next/link";

export default async function AdminCustomerDetail({ params }: { params: Promise<{ id: string }> }) {
  const session = await getServerSession(authOptions);
  if (!session || (session.user as any)?.role !== "ADMIN") redirect("/dashboard");
  const { id } = await params;
  const customer = await db.user.findUnique({ where: { id }, include: { accounts: true, virtualCards: true, cryptoHoldings: true, transactions: { orderBy: { createdAt: "desc" }, take: 10 }, auditLogs: { orderBy: { createdAt: "desc" }, take: 10 } } });
  if (!customer) redirect("/admin/customers");

  return <div className="min-h-screen bg-slate-950 text-slate-100"><header className="border-b border-slate-800 bg-slate-950/95"><div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-5 sm:px-8"><Link href="/admin" className="text-sm font-semibold text-white">Civic<span className="text-red-400">Bank</span> Admin</Link><Link href="/admin/customers" className="text-xs text-indigo-400">Back to customers</Link></div></header><main className="mx-auto max-w-7xl space-y-6 p-5 sm:p-8"><div className="flex flex-col gap-4 rounded-2xl border border-slate-800 bg-slate-900 p-6 sm:flex-row sm:items-center"><div className="flex h-16 w-16 items-center justify-center overflow-hidden rounded-2xl bg-indigo-500/10 text-xl font-semibold text-indigo-300">{customer.image ? <img src={customer.image} alt="" className="h-full w-full object-cover" /> : (customer.name || customer.email).charAt(0).toUpperCase()}</div><div><p className="text-[10px] font-semibold uppercase tracking-widest text-red-400">Customer profile</p><h1 className="mt-1 text-xl font-semibold text-white">{customer.name || "Unnamed customer"}</h1><p className="mt-1 text-sm text-slate-400">{customer.email} · {customer.role}</p></div></div><div className="grid grid-cols-1 gap-5 lg:grid-cols-3"><section className="rounded-2xl border border-slate-800 bg-slate-900 p-5 lg:col-span-2"><h2 className="text-sm font-semibold text-white">Accounts</h2><div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">{customer.accounts.map((account) => <div key={account.id} className="rounded-xl border border-slate-800 bg-slate-950 p-4"><div className="flex justify-between text-xs"><span className="text-indigo-300">{account.currency} {account.type}</span><span className="text-emerald-400">{account.status}</span></div><p className="mt-3 font-mono text-xl text-white">{Number(account.balance).toLocaleString(undefined, { minimumFractionDigits: 2 })}</p><p className="mt-1 font-mono text-[10px] text-slate-500">•••• {account.accountNumber.slice(-4)}</p></div>)}</div>{!customer.accounts.length && <p className="mt-4 text-xs text-slate-500">No accounts.</p>}</section><section className="rounded-2xl border border-slate-800 bg-slate-900 p-5"><h2 className="text-sm font-semibold text-white">Products</h2><div className="mt-4 space-y-3 text-xs text-slate-400"><p>Virtual cards: <strong className="text-white">{customer.virtualCards.length}</strong></p><p>Crypto holdings: <strong className="text-white">{customer.cryptoHoldings.length}</strong></p><p>Transactions: <strong className="text-white">{customer.transactions.length} recent</strong></p><p>Audit events: <strong className="text-white">{customer.auditLogs.length} recent</strong></p></div></section></div><section className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900"><div className="border-b border-slate-800 p-5"><h2 className="text-sm font-semibold text-white">Recent transactions</h2></div><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="text-[10px] uppercase tracking-wider text-slate-500"><th className="px-5 py-3">Reference</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">Amount</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Date</th></tr></thead><tbody className="divide-y divide-slate-800">{customer.transactions.map((transaction) => <tr key={transaction.id} className="text-xs text-slate-300"><td className="px-5 py-4 font-mono text-indigo-300">{transaction.reference}</td><td className="px-5 py-4">{transaction.type}</td><td className="px-5 py-4 font-mono">${Number(transaction.amount).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td><td className="px-5 py-4">{transaction.status}</td><td className="px-5 py-4 text-slate-500">{transaction.createdAt.toLocaleString()}</td></tr>)}{!customer.transactions.length && <tr><td colSpan={5} className="px-5 py-10 text-center text-xs text-slate-500">No transactions.</td></tr>}</tbody></table></div></section></main></div>;
}